/*
 * Differential test against the prototype.
 *
 * `__golden__/prototype.json` holds what design/planner-v65.html itself answered
 * for a few hundred inputs (generated by `node scripts/planner-golden.mjs`, with
 * a fixed clock of 2026-11-10). Every case is replayed through the TypeScript
 * port, which must give the same numbers and the same Czech words.
 *
 * The port speaks `categoryId` where the prototype says `type`, and
 * `clubBooked/publicBooked/released` where it says `demoClub/demoPublic/
 * demoReleased`; `toSession` is the only translation.
 */
import { describe, expect, it } from 'vitest';
import golden from './__golden__/prototype.json';
import {
  addPlannedInterval, agendaEvents, agendaHours, agendaPanelModel, bookingState, canSafelyMerge, clockDuration,
  collectAdjacentBlocks, commitTermExpansion, computeDayPlan, confirmTermMovement, dayReservationSummary, dayTooltipModel,
  detailedDate, initialAgendaUi, isoWeek, makeSlots, miniCellModel, monthViewModel, dayViewModel, orderCommandModel,
  orderSnapshot, pendingMinutes, planCardModel, plannedFrom, plannedOf, proposalForMove, proposalForTermExpansion,
  selectionFromPointer, smartSlotShift, timeLeft, totals, validatePlacement, validateTermExpansion, validateTermMove,
  weekEventsModel, weekHeadModel, makeContext, DEFAULT_WINDOW, dateOf, mondayOf, monthStartOf, pointerCoords,
  type ClubProfile, type PlannerContext, type PlannerSession, type Preview, type ResizeDrag,
} from './index';

/* eslint-disable @typescript-eslint/no-explicit-any */
const g = golden as unknown as Record<string, any>;

const PUBLIC_DEMO_IDS = new Set(['v1', 'p1', 'a2']);
const DECK_ORDER = ['medical', 'movement', 'fitness', 'physio', 'vo2', 'performance'];
const SHORT: Record<string, string> = { medical: 'Prohlídky', movement: 'Pohyb', fitness: 'Kondice', physio: 'Fyzio', vo2: 'VO₂max', performance: 'Výkon' };

function toSession(e: any): PlannerSession {
  const { type, demoClub, demoPublic, demoReleased, visualHour: _vh, visualHeight: _vH, ...rest } = e;
  const s: any = { ...rest, categoryId: type };
  if (demoClub !== undefined) s.clubBooked = demoClub;
  if (demoPublic !== undefined) s.publicBooked = demoPublic;
  if (demoReleased !== undefined) s.released = demoReleased;
  if (PUBLIC_DEMO_IDS.has(e.id)) s.origin = 'public';
  return s;
}

function ctxFrom(events: any[], budget = 720): PlannerContext {
  return makeContext({
    categories: (g.categoryOrder as string[]).map((id) => ({
      id,
      name: g.category[id].name,
      shortName: SHORT[id],
      iconKey: g.category[id].icon,
      color: g.category[id].color,
      subtitle: g.demand[id].subtitle,
      slotMinutes: g.demand[id].duration,
    })),
    demands: DECK_ORDER.map((id) => ({ categoryId: id, requested: g.demand[id].requested, baselinePlanned: g.demand[id].planned })),
    baselineSessions: (g.initialEvents as any[]).map((e) => ({
      id: e.id, categoryId: e.type, capacity: e.capacity, origin: PUBLIC_DEMO_IDS.has(e.id) ? ('public' as const) : e.origin,
    })),
    sessions: events.map(toSession),
    dayBudgetMinutes: budget,
    today: '2026-11-10',
    window: DEFAULT_WINDOW,
  });
}

const freshCtx = (budget = 720) => ctxFrom(g.initialEvents, budget);
const protoEv = (id: string, date: string, start: string, end: string, type: string, capacity: number, extra: Record<string, unknown> = {}) =>
  ({ id, date, start, end, type, capacity, booked: 0, showInList: true, ...extra });

const preview = (p: any): Preview => {
  const { type, ...rest } = p;
  return { ...rest, ...(type ? { categoryId: type } : {}), kind: p.kind ?? 'place' } as Preview;
};

const stripPlan = (p: ReturnType<typeof computeDayPlan>) => ({
  date: p.date, minutes: p.minutes, ratio: p.ratio, percent: p.percent, slots: p.slots,
  entries: p.entries.map((e) => ({ id: e.id, type: e.categoryId, start: e.start, end: e.end, capacity: e.capacity, extraPreview: e.extraPreview, date: e.date })),
  slices: p.slices.map((s) => ({ type: s.categoryId, minutes: s.minutes, terms: s.terms, slots: s.slots })),
});

describe('prototype fixtures', () => {
  it('has the 18 sample terms and the 6 demo categories the tests assume', () => {
    expect(g.initialEvents).toHaveLength(18);
    expect(g.categoryOrder).toEqual(['medical', 'vo2', 'movement', 'fitness', 'physio', 'performance']);
    expect(g.demand.medical).toMatchObject({ requested: 72, planned: 48, duration: 20 });
  });
});

describe('time helpers', () => {
  it('formats durations', () => {
    for (const [n, text] of g.helpers.timeLeft) expect(timeLeft(n)).toBe(text);
    for (const [n, text] of g.helpers.clockDuration) expect(clockDuration(n)).toBe(text);
    for (const [n, text] of g.helpers.agendaHours) expect(agendaHours(n)).toBe(text);
  });
  it('numbers ISO weeks and names days', () => {
    for (const [d, w] of g.helpers.isoWeek) expect(isoWeek(dateOf(d))).toBe(w);
    for (const [d, text] of g.helpers.detailedDate) expect(detailedDate(d)).toBe(text);
  });
  it('builds slots', () => {
    for (const [s, q, d, expected] of g.helpers.makeSlots) expect(makeSlots(s, q, d)).toEqual(expected);
  });
});

describe('day plan (mini-calendar ring)', () => {
  const ctx = freshCtx();
  it('plans every day of the sample month exactly like the prototype', () => {
    for (const day of g.dayPlan.days) expect(stripPlan(computeDayPlan(ctx, day.date))).toEqual(day);
  });
  it('draws the same arcs and liquid level', () => {
    const arcRe = /stroke="([^"]+)" stroke-dasharray="([\d.]+) ([\d.]+)" stroke-dashoffset="(-?[\d.]+)"/g;
    const check = (budget: number, date: string, html: string, pv?: Preview) => {
      const model = miniCellModel(freshCtx(budget), date, pv);
      const arcs = [...html.matchAll(arcRe)];
      if (!arcs.length) {
        expect(model.ring).toBeNull();
        return;
      }
      expect(model.ring).not.toBeNull();
      expect(model.ring!.arcs).toHaveLength(arcs.length);
      model.ring!.arcs.forEach((arc, i) => {
        const m = arcs[i]!;
        expect(arc.color).toBe(m[1]);
        expect(arc.dash.toFixed(2)).toBe(m[2]);
        expect(model.ring!.circumference.toFixed(2)).toBe(m[3]);
        expect(arc.offset.toFixed(2)).toBe(m[4]);
      });
      expect(`${model.ring!.liquidPercent.toFixed(3)}%`).toBe(/--liquid-fill:([\d.]+%)/.exec(html)![1]);
      expect(String(model.dayNumber)).toBe(/class="day-number">(\d+)</.exec(html)![1]);
    };
    for (const [d, html] of g.miniContent) check(720, d, html);
    for (const c of g.dayPlanBudget480) check(480, c.plan.date, c.html);
    for (const c of g.dayPlanBudget1440) check(1440, c.plan.date, c.html);
  });
  it('projects previews (placement, move, resize) onto the days', () => {
    for (const c of g.dayPlanPreview) {
      const pv = preview(c.preview);
      for (const day of c.days) {
        expect(stripPlan(computeDayPlan(ctx, day.plan.date, pv)), `${c.name} ${day.plan.date}`).toEqual(day.plan);
      }
    }
  });
  it('labels the day button for assistive tech', () => {
    expect(miniCellModel(ctx, '2026-11-18').ariaLabel).toBe('18. 11. 2026 · 2 termínů · 20 slotů · 29% plánovací kapacity');
  });
});

describe('day flyout', () => {
  const ctx = freshCtx();
  it('matches the prototype tooltip', () => {
    for (const t of g.tooltip) {
      const model = dayTooltipModel(ctx, t.date, false);
      if (t.heading === null) {
        expect(model).toBeNull();
        continue;
      }
      expect(model!.heading).toBe(t.heading);
      expect(`${model!.percent}%`).toBe(t.pct);
      expect([model!.plannedLabel, model!.referenceLabel]).toEqual(t.caption);
      expect([`${model!.stats.terms}Termíny`, `${model!.stats.slots}Sloty`, `${model!.stats.plannedTime}Plánovaný čas`]).toEqual(t.stats);
      expect(model!.events.map((e) => `${e.name}${e.meta}${e.slotsLabel}`)).toEqual(t.events);
      expect(model!.bars.map((b) => `width:${b.widthPercent.toFixed(2)}%;background:${b.color};color:${b.color}`)).toEqual(t.bars);
    }
  });
});

