describe('order planning', () => {
  it('computes planned / totals / command panel / snapshot for each scenario', () => {
    for (const s of g.order) {
      const ctx = ctxFrom(s.events);
      for (const [type, planned] of Object.entries(s.plannedOf)) expect(plannedOf(ctx, type), `${s.name} ${type}`).toBe(planned);
      expect(totals(ctx), s.name).toEqual(s.totals);
      expect(pendingMinutes(ctx), s.name).toBe(s.pendingMinutes);
      const snap = orderSnapshot(ctx, { clubName: 'x' } as ClubProfile);
      expect(snap.terms.map((e) => e.id), s.name).toEqual(s.snapshot.terms.map((e: any) => e.id));
      expect(snap.slots, s.name).toBe(s.snapshot.slots);
      expect(snap.rows.map((r) => [r.categoryId, r.requested, r.planned, r.remaining, r.percent, r.slotMinutes]), s.name)
        .toEqual(s.snapshot.rows.map((r: any) => [r.type, r.requested, r.planned, r.remaining, r.percent, r.duration]));
      expect(snap.issues.filter((i) => i !== 'Chybí kontakt klubu'), s.name).toEqual(s.snapshot.issues.filter((i: string) => i !== 'Chybí kontakt klubu'));
      const cmd = orderCommandModel(ctx);
      expect(`${cmd.percent}%`, s.name).toBe(s.command.percent);
      expect(`${cmd.planned} / ${cmd.requested}`, s.name).toBe(s.command.total);
      expect(cmd.remainingText, s.name).toBe(s.command.remaining);
      expect(String(cmd.terms), s.name).toBe(s.command.terms);
      expect(String(cmd.newSlots), s.name).toBe(s.command.slots);
    }
  });
  it('renders the same carousel cards', () => {
    for (const s of g.order) {
      const ctx = ctxFrom(s.events);
      const cards = DECK_ORDER.map((id) => planCardModel(ctx, id, '2026-11-16', null));
      expect(cards.map((c) => c.categoryId), s.name).toEqual(s.cards.map((c: any) => c.type));
      cards.forEach((c, i) => {
        const p = s.cards[i];
        expect(`${c.percent}%`, `${s.name} ${c.categoryId}`).toBe(p.ring);
        expect(`${c.planned} / ${c.requested}`).toBe(p.num);
        expect(c.remainingText).toBe(p.remaining);
        expect(c.durationText).toBe(p.duration);
        expect(c.bottomText).toBe(p.bottom);
        expect(c.title).toBe(p.title);
        expect(c.done).toBe(p.complete);
        expect(c.chart.map((b) => [`${b.height}px`, String(b.opacity)])).toEqual(p.chart);
      });
    }
  });
});

