describe('dragging a činnost into the board', () => {
  const ctx = freshCtx();
  const rect = { left: 100, top: 50, width: 1000, height: 455 };
  it('proposes the same interval for each pointer position', () => {
    for (const c of g.selection.cases) {
      const point = pointerCoords(rect, rect.left + c.fx * rect.width, rect.top + c.fy * rect.height);
      const r = selectionFromPointer(ctx, c.drag, c.type, g.selection.weekStart, point);
      const label = `${c.type} ${JSON.stringify(c.drag)} ${c.fx},${c.fy}`;
      if (c.result === null) {
        expect(r, label).toBeNull();
        continue;
      }
      const { type, ...expected } = c.result;
      expect(r, label).toMatchObject({ ...expected, categoryId: type });
    }
  });
});

describe('merging and addPlannedInterval', () => {
  it('merges (or refuses) exactly like the prototype', () => {
    for (const c of g.addInterval) {
      const ctx = ctxFrom(c.before);
      let n = 0;
      const result = addPlannedInterval(ctx, { date: c.input.date, categoryId: c.input.type, start: c.input.start, quantity: c.input.quantity }, () => `NEW${n++}`);
      if (!result.ok) {
        // prototype: nothing changed
        expect(result.sessions.map((e) => e.id), c.name).toEqual(c.after.map((e: any) => e.id));
        continue;
      }
      const norm = (e: any) => ({ date: e.date, start: e.start, end: e.end, type: e.type ?? e.categoryId, capacity: e.capacity, booked: e.booked, createdByPlanner: !!e.createdByPlanner });
      const mine = result.sessions.map(norm);
      const theirs = (c.after as any[]).map(norm);
      expect(mine, c.name).toEqual(theirs);
      // ids survive for the leftmost merged block and for untouched terms
      const protoIds = (c.after as any[]).map((e) => (String(e.id).startsWith('plan-') ? 'NEW0' : e.id));
      expect(result.sessions.map((e) => e.id), c.name).toEqual(protoIds);
      expect(result.complete, c.name).toBe(c.name === 'completes-medical');
    }
  });
  it('lists adjacent safe blocks including the bridge case', () => {
    const A = toSession(protoEv('A', '2026-11-25', '09:00', '10:00', 'medical', 3, { createdByPlanner: true, slotDuration: 20 }));
    const B = toSession(protoEv('B', '2026-11-25', '11:00', '12:00', 'medical', 3, { createdByPlanner: true, slotDuration: 20 }));
    const ctx = makeContext({ ...freshCtx(), sessions: [A, B] });
    const term = toSession(protoEv('N', '2026-11-25', '10:00', '11:00', 'medical', 3));
    const chain = collectAdjacentBlocks(ctx, term);
    expect(chain).toMatchObject({ start: '09:00', end: '12:00' });
    expect(chain.group.map((e) => e.id)).toEqual(['A', 'B']);
    expect(canSafelyMerge(ctx, A, term)).toBe(true);
    expect(canSafelyMerge(ctx, { ...A, booked: 1 }, term)).toBe(false);
  });
});

describe('moving a term', () => {
  const extra = [
    protoEv('nm1', '2026-11-25', '09:00', '10:00', 'medical', 3, { createdByPlanner: true, slotDuration: 20 }),
    protoEv('nr1', '2026-11-24', '10:00', '11:00', 'physio', 2, { createdByPlanner: true, slotDuration: 30 }),
  ];
  const ctx = ctxFrom([...g.initialEvents, ...extra]);
  const rect = { left: 100, top: 50, width: 1000, height: 455 };
  it('proposes the same move for each pointer position', () => {
    for (const c of g.moves) {
      const r = proposalForMove(ctx, { id: c.id, grabOffset: c.grab }, { clientX: rect.left + c.fx * rect.width, clientY: rect.top + c.fy * rect.height }, rect, '2026-11-16');
      const { type, ...expected } = c.result;
      expect(r, JSON.stringify([c.id, c.grab, c.fx, c.fy])).toMatchObject({ ...expected, categoryId: type });
    }
  });
  it('validates the move table', () => {
    for (const c of g.validateMove) {
      const original = ctx.sessions.find((e) => e.id === c.id)!;
      expect(validateTermMove(ctx, original, c.date, c.start, c.end, c.inside), JSON.stringify(c)).toEqual(c.result);
    }
  });
  it('shifts the term and its slot coordinates when confirmed', () => {
    const slotted = protoEv('sl1', '2026-11-26', '09:00', '10:00', 'medical', 3, {
      createdByPlanner: true, slotDuration: 20,
      slots: g.commitMove.before.slots,
    });
    const c2 = ctxFrom([...g.initialEvents.filter((e: any) => e.id !== 'x1'), ...extra, slotted]);
    const r = confirmTermMovement(c2, 'sl1', g.commitMove.proposal);
    expect(r.ok).toBe(true);
    const after = r.sessions.find((e) => e.id === 'sl1')!;
    const expected = g.commitMove.after;
    expect({ date: after.date, start: after.start, end: after.end, slots: after.slots }).toEqual({ date: expected.date, start: expected.start, end: expected.end, slots: expected.slots });
    expect(confirmTermMovement(c2, 'sl1', { date: '2026-11-18', start: '09:00', end: '10:00' }).reason).toMatch(/^Přesun nelze potvrdit: Kolize/);
    expect(confirmTermMovement(c2, 'nope', g.commitMove.proposal).reason).toBe('Termín již neexistuje.');
  });
});

describe('expanding a term', () => {
  const extra = [
    protoEv('nm1', '2026-11-25', '09:00', '10:00', 'medical', 3, { createdByPlanner: true, slotDuration: 20 }),
    protoEv('nr1', '2026-11-24', '10:00', '11:00', 'physio', 2, { createdByPlanner: true, slotDuration: 30 }),
  ];
  const ctx = ctxFrom([...g.initialEvents, ...extra]);
  it('proposes the same expansion for each pointer travel', () => {
    for (const c of g.resizes) {
      const original = ctx.sessions.find((e) => e.id === c.id)!;
      const drag: ResizeDrag = { id: c.id, original, edge: c.edge, pointerId: 1, originY: 1000, started: true };
      const r = proposalForTermExpansion(ctx, drag, 1000 + c.dy, c.scale, '2026-11-16');
      const { type, original: _o, ...expected } = c.result;
      expect(r, JSON.stringify([c.id, c.edge, c.dy])).toMatchObject({ ...expected, categoryId: type });
    }
  });
  it('validates the expansion table', () => {
    for (const c of g.validateExpansion) {
      const original = ctx.sessions.find((e) => e.id === c.id)!;
      expect(validateTermExpansion(ctx, original, c.edge, c.extra, c.ns, c.ne), JSON.stringify(c)).toEqual(c.result);
    }
  });
  it('appends slots without rewriting existing ones', () => {
    const { bottom, top } = g.commitExpand;
    for (const [name, c] of [['bottom', bottom], ['top', top]] as const) {
      const original = toSession(c.original);
      const cx = ctxFrom([...g.initialEvents.filter((e: any) => e.id !== 'x1'), ...extra.map((e) => (e.id === c.original.id ? c.original : e))]);
      const proposal = { ...c.proposal, categoryId: c.proposal.type, original } as any;
      const r = commitTermExpansion(cx, original, proposal, 'STAMP');
      expect(r.ok, name).toBe(true);
      const after = r.term!;
      const norm = (s: any) => ({ start: s.start, end: s.end, id: String(s.id) });
      expect({ start: after.start, end: after.end, capacity: after.capacity, slots: after.slots!.map(norm) }, name).toEqual({
        start: c.after.start, end: c.after.end, capacity: c.after.capacity, slots: c.after.slots.map(norm),
      });
    }
  });
  it('refuses a stale term', () => {
    const original = ctx.sessions.find((e) => e.id === 'nm1')!;
    const proposal = proposalForTermExpansion(ctx, { id: 'nm1', original, edge: 'bottom', pointerId: 1, originY: 0, started: true }, 120, 1, '2026-11-16')!;
    const changed = makeContext({ ...ctx, sessions: ctx.sessions.map((e) => (e.id === 'nm1' ? { ...e, capacity: 4, end: '10:20' } : e)) });
    expect(commitTermExpansion(changed, original, proposal).reason).toBe('Termín byl mezitím změněn. Rozšíření proveďte znovu.');
  });
});

